import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:archive/archive.dart';

import '../lib/src/comics/comic_catalog.dart';
import '../lib/src/comics/comic_files.dart';

// Generated by Android's archive 4.1 ZipFileEncoder.zipDirectory with a
// 0001-第一话/ directory and a real 2x2 PNG. The directory has method=deflate,
// compressedSize=0 and uncompressedSize=0, so ordinary unzip -t rejects it.
const _androidZip =
    'UEsDBBQAAAgIAHlKTF0AAAAAAAAAAAAAAAAPAAAAMDAwMS3nrKzkuIDor50v'
    'UEsDBBQAAAgIAHlKTF13lWqjRQAAAEcAAAAXAAAAMDAwMS3nrKzkuIDor50v'
    'MDAwMS5wbmfrDPBz5+WS4mJgYOD19HAJYmBgYAJhDhD598qsYgYGBj5P'
    'F8eQijnJiQzMYhysDAxJDJxHVstfZmBgYPB09XNZ55TQBABQSwECFAAU'
    'AAAICAB5SkxdAAAAAAAAAAAAAAAADwAAAAAAAAAAAAAA/0EAAAAAMDAwMS3n'
    'rKzkuIDor50vUEsBAhQAFAAACAgAeUpMXXeVaqNFAAAARwAAABcAAAAAAA'
    'AAAAAAALaBLQAAADAwMDEt56ys5LiA6K+dLzAwMDEucG5nUEsFBgAAAAAC'
    'AAIAggAAAKcAAAAAAA==';

Future<void> main() async {
  final root = await Directory.systemTemp.createTemp('comic-zip-compatibility-');
  try {
    final files = ComicFiles(root.path, 64 * 1024 * 1024);
    Future<void> verify(List<int> bytes) async {
      final file = File('${root.path}/comic.zip');
      await file.writeAsBytes(bytes);
      await files.verify(ComicTemporaryFile(file, bytes.length, ''), 'zip');
    }

    Future<void> reject(List<int> bytes, String label) async {
      try {
        await verify(bytes);
      } on ComicFailure catch (error) {
        if (error.code == 'invalid_comic_content') return;
        rethrow;
      }
      throw StateError('Accepted invalid ZIP: $label');
    }

    final original = base64Decode(_androidZip);
    await verify(original);
    final file = File('${root.path}/comic.zip');
    if (base64Encode(await file.readAsBytes()) != _androidZip) {
      throw StateError('Validation changed the original Android ZIP');
    }

    // Excluding directory placeholders must not bypass file CRC checks.
    final corrupt = Uint8List.fromList(original);
    final headers = <int>[];
    final data = ByteData.sublistView(corrupt);
    for (var i = 0; i <= corrupt.length - 4; i++) {
      if (data.getUint32(i, Endian.little) == 0x02014b50) headers.add(i);
    }
    corrupt[headers[1] + 16] ^= 1; // Central directory image CRC.
    final imageHeader = data.getUint32(headers[1] + 42, Endian.little);
    corrupt[imageHeader + 14] ^= 1; // Matching local CRC, wrong for the data.
    await reject(corrupt, 'image CRC');

    final directoryPayload = Uint8List.fromList(original);
    ByteData.sublistView(directoryPayload)
        .setUint32(headers.first + 24, 1, Endian.little);
    await reject(directoryPayload, 'directory with nonempty content');

    await reject(
        ZipEncoder().encode(Archive()
          ..addFile(ArchiveFile('../001.jpg', 4, [255, 216, 255, 217])))!,
        'path traversal');

    // New Android packages omit directory entries but retain chapter paths.
    await verify(ZipEncoder().encode(Archive()
      ..addFile(ArchiveFile('0001/001.jpg', 4, [255, 216, 255, 217])))!);
    print('Comic ZIP compatibility and corruption checks passed.');
  } finally {
    await root.delete(recursive: true);
  }
}
